<script>
  (function() {
    const root = document.documentElement;
    const tok = (n) => getComputedStyle(root).getPropertyValue(n).trim();
    const canvas = document.getElementById('stage');
    const ctx = canvas.getContext('2d');
    const W = 680, H = 360;
    let lr1 = 0.01, lr2 = 0.10, lr3 = 0.50;
    let stepCount = 1;
    let isRunning = true;
    const lr1Slider = document.getElementById('lr1-slider');
    const lr2Slider = document.getElementById('lr2-slider');
    const lr3Slider = document.getElementById('lr3-slider');
    const lr1Val = document.getElementById('lr1-val');
    const lr2Val = document.getElementById('lr2-val');
    const lr3Val = document.getElementById('lr3-val');
    const stepDisplay = document.getElementById('stepDisplay');
