        ink: tok('--ink'),
        accent: tok('--accent'),
        line: tok('--line'),
        text2: tok('--text2'),
        bg: tok('--bg'),
        card: tok('--card'),
      };
    }

    function gradientDescent(lr, steps) {
      let x = 2.0;
      const pts = [x];
      for (let i = 0; i < steps; i++) {
        x = x - lr * 2 * x;
        pts.push(x);
      }
      return pts;
    }

    function mapX(x) { return 40 + (x + 2.5) / 5 * (W - 80); }
    function mapY(y) { return H - 30 - (y / 6.5) * (H - 60); }

    function draw() {
      const C = getColors();
      const dark = root.getAttribute('data-theme') === 'lab' || root.getAttribute('data-theme')?.includes('dark');
      ctx.clearRect(0, 0, W, H);

      // 网格
      ctx.strokeStyle = C.line;
      ctx.lineWidth = 0.5;
      ctx.setLineDash([3, 4]);
      for (let x = -2; x <= 2; x += 1) {
        const px = mapX(x);
        ctx.beginPath(); ctx.moveTo(px, 30); ctx.lineTo(px, H - 30); ctx.stroke();
      }
      for (let y = 0; y <= 6; y += 1) {
        const py = mapY(y);
        ctx.beginPath(); ctx.moveTo(40, py); ctx.lineTo(W - 40, py); ctx.stroke();
      }
      ctx.setLineDash([]);

      // 坐标轴
      ctx.strokeStyle = C.text2;
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(40, mapY(0)); ctx.lineTo(W - 40, mapY(0)); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(mapX(0), 30); ctx.lineTo(mapX(0), H - 30); ctx.stroke();

      // f(x)=x² 曲线
      ctx.strokeStyle = C.ink;
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      for (let px = 40; px <= W - 40; px += 1) {
        const x = (px - 40) / (W - 80) * 5 - 2.5;
        const y = x * x;
        const py = mapY(y);
        if (px === 40) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;

      // 三条轨迹
      const configs = [
        { lr: lr1, color: C.accent, label: 'η₁' },
        { lr: lr2, color: C.accent, label: 'η₂' },
        { lr: lr3, color: C.accent, label: 'η₃' },
      ];

      configs.forEach((cfg, idx) => {
        const pts = gradientDescent(cfg.lr, stepCount);
        // 用不同透明度区分三条线
        const alpha = [0.9, 0.6, 0.3][idx];
        ctx.strokeStyle = cfg.color;
        ctx.lineWidth = 2;
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        for (let i = 0; i < pts.length; i++) {
          const px = mapX(pts[i]);
          const py = mapY(pts[i] * pts[i]);
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.stroke();
        ctx.globalAlpha = 1;

        // 圆点
        for (let i = 0; i < pts.length; i++) {
          const px = mapX(pts[i]);
          const py = mapY(pts[i] * pts[i]);
          ctx.fillStyle = cfg.color;
          ctx.globalAlpha = alpha;
          ctx.beginPath(); ctx.arc(px, py, 4, 0, Math.PI * 2); ctx.fill();
          ctx.globalAlpha = 1;
          if (dark) {
            ctx.shadowColor = cfg.color;
            ctx.shadowBlur = 8;
            ctx.beginPath(); ctx.arc(px, py, 4, 0, Math.PI * 2); ctx.fill();
            ctx.shadowBlur = 0;
          }
        }

        // 末端标注
        if (pts.length > 0) {
          const lastX = pts[pts.length - 1];
          const px = mapX(lastX);
          const py = mapY(lastX * lastX);
          ctx.fillStyle = C.text2;
          ctx.font = '11px ' + tok('--mono');
          ctx.textAlign = 'left';
          ctx.textBaseline = 'bottom';
          const label = 'x=' + lastX.toFixed(3);
          const metrics = ctx.measureText(label);
          const tw = metrics.width;
          const th = 14;
          ctx.fillStyle = C.card + 'cc';
          ctx.fillRect(px + 6, py - th - 2, tw + 6, th + 4);
          ctx.fillStyle = cfg.color;
          ctx.globalAlpha = alpha;
          ctx.fillText(label, px + 9, py - 2);
          ctx.globalAlpha = 1;
        }
      });

      // 刻度尺
      ctx.strokeStyle = C.line;
      ctx.lineWidth = 0.5;
      for (let x = -2; x <= 2; x += 1) {
        const px = mapX(x);
        ctx.beginPath(); ctx.moveTo(px, H - 30); ctx.lineTo(px, H - 24); ctx.stroke();
        ctx.fillStyle = C.text2;
        ctx.font = '10px ' + tok('--mono');
        ctx.textAlign = 'center';
        ctx.textBaseline = 'top';
        ctx.fillText(x.toFixed(0), px, H - 22);
      }
      for (let y = 0; y <= 6; y += 1) {
        const py = mapY(y);
        ctx.beginPath(); ctx.moveTo(40, py); ctx.lineTo(46, py); ctx.stroke();
        ctx.fillStyle = C.text2;
        ctx.font = '10px ' + tok('--mono');
        ctx.textAlign = 'right';
        ctx.textBaseline = 'middle';
        ctx.fillText(y.toFixed(0), 36, py);
      }
      ctx.fillStyle = C.text2;
      ctx.font = '11px ' + tok('--sans');
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText('x', W - 30, mapY(0) + 4);
      ctx.textAlign = 'right';
      ctx.textBaseline = 'bottom';
      ctx.fillText('f(x)', 44, 34);
    }

    function update() {
      lr1 = parseFloat(lr1Slider.value);
      lr2 = parseFloat(lr2Slider.value);
      lr3 = parseFloat(lr3Slider.value);
      lr1Val.textContent = lr1.toFixed(2);
      lr2Val.textContent = lr2.toFixed(2);
      lr3Val.textContent = lr3.toFixed(2);
      stepDisplay.textContent = stepCount;
      draw();
    }

